<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { platformApi, statusText } from '../api'
import PageState from '../components/PageState.vue'
import ModalDialog from '../components/ModalDialog.vue'
import FilterSelect from '../components/FilterSelect.vue'
const templates=ref<any[]>([]);const modules=ref<any[]>([]);const tenants=ref<any[]>([]);const loading=ref(false);const saving=ref(false);const error=ref('');const notice=ref('');const current=ref<any>(null);const modal=ref(false);const selectedPermissions=reactive<Record<string,boolean>>({});const selectedTemplates=reactive<Record<string,boolean>>({});const targetTenant=ref('');const form=reactive({code:'',name:'',description:'',status:'active',sort_no:100})
const kindText: Record<string,string> = { read: '读', write: '写', action: '操作' }
async function load(){loading.value=true;error.value='';try{const[t,m,tn]=await Promise.all([platformApi<{items:any[]}>('/role-templates'),platformApi<{items:any[]}>('/permissions'),platformApi<{items:any[]}>('/tenants')]);templates.value=t.items;modules.value=m.items;tenants.value=tn.items}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function closeModal(){modal.value=false;current.value=null}
function open(item:any){current.value=item||null;Object.assign(form,item?{code:item.code,name:item.name,description:item.description,status:item.status,sort_no:item.sort_no}:{code:'',name:'',description:'',status:'active',sort_no:100});Object.keys(selectedPermissions).forEach(k=>delete selectedPermissions[k]);if(item)item.permission_codes.forEach((code:string)=>selectedPermissions[code]=true);modal.value=true}
async function createTemplate(){saving.value=true;error.value='';try{const created=await platformApi<{id:string}>('/role-templates',{method:'POST',body:JSON.stringify(form)});await platformApi(`/role-templates/${created.id}/permissions`,{method:'PUT',body:JSON.stringify({permission_codes:Object.keys(selectedPermissions).filter(k=>selectedPermissions[k])})});notice.value='角色模板及权限已创建';modal.value=false;current.value=null;await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function saveTemplate(){if(!current.value)return;saving.value=true;error.value='';try{await platformApi(`/role-templates/${current.value.id}`,{method:'PATCH',body:JSON.stringify({name:form.name,description:form.description,sort_no:form.sort_no,status:form.status})});await platformApi(`/role-templates/${current.value.id}/permissions`,{method:'PUT',body:JSON.stringify({permission_codes:Object.keys(selectedPermissions).filter(k=>selectedPermissions[k])})});notice.value='角色模板及权限已保存';modal.value=false;current.value=null;await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function deleteTemplate(item:any){if(!window.confirm(`确认删除平台角色模板 ${item.name}？已被租户使用的模板不能删除。`))return;error.value='';try{await platformApi(`/role-templates/${item.id}`,{method:'DELETE'});notice.value=`模板 ${item.name} 已删除`;if(current.value?.id===item.id){current.value=null;modal.value=false}await load()}catch(e){error.value=(e as Error).message}}
async function apply(){if(!targetTenant.value){error.value='请选择目标租户';return};const ids=Object.keys(selectedTemplates).filter(k=>selectedTemplates[k]);if(!ids.length){error.value='请选择至少一个角色模板';return};saving.value=true;error.value='';try{const result=await platformApi<{created_roles:string[];updated_roles:string[]}>('/tenants/'+targetTenant.value+'/apply-role-templates',{method:'POST',body:JSON.stringify({template_ids:ids})});notice.value=`模板已应用：新增 ${result.created_roles.length} 个角色，更新 ${result.updated_roles.length} 个角色`;await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
onMounted(load)
</script>
<template><div style="max-width:1500px;margin:auto;padding:28px"><div class="page-header"><div><h1>用户角色权限模板</h1><p>平台统一定义多套租户角色及权限，可初始化新租户或已有租户</p></div><div class="header-actions"><RouterLink to="/platform/tenants" class="button secondary">返回平台控制面</RouterLink><button class="button" @click="open(null)">+ 新增模板</button></div></div><div v-if="error" class="notice error">{{error}}</div><div v-if="notice" class="notice success">{{notice}}</div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><h2>模板列表</h2></div><PageState :loading="loading"/><div v-if="!loading" class="table-wrap"><table><thead><tr><th>选择初始化</th><th>编码</th><th>名称</th><th>权限数</th><th>租户使用数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in templates"><td><input v-model="selectedTemplates[item.id]" type="checkbox"></td><td>{{item.code}}</td><td>{{item.name}}</td><td>{{item.permission_codes.length}}</td><td>{{item.tenant_use_count}}</td><td><span class="status" :class="item.status">{{statusText[item.status]}}</span></td><td><button class="button link" @click="open(item)">编辑</button><button class="button link text-danger" :disabled="item.tenant_use_count>0" @click="deleteTemplate(item)">删除</button></td></tr></tbody></table></div></section><section class="panel"><div class="panel-header"><h2>应用到租户</h2></div><div class="panel-body"><div class="field"><label>目标租户</label><FilterSelect v-model="targetTenant" :options="tenants.map(item=>({value:item.id,label:item.code+' · '+item.name}))" placeholder="请选择租户"/></div><p class="text-muted">将按所选模板在目标租户内创建或更新同编码角色；不会修改固定租户管理员。</p><div class="form-actions"><button class="button" :disabled="saving" @click="apply">初始化所选模板</button></div></div></section></div><ModalDialog v-if="modal" wide :title="current?`编辑模板 · ${current.name}`:'新增角色模板'" @close="closeModal"><div v-if="error" class="notice error">{{error}}</div><div class="form-grid"><div class="field"><label>模板编码</label><input v-model.trim="form.code" :disabled="!!current" placeholder="factory_manager"></div><div class="field"><label>模板名称</label><input v-model.trim="form.name"></div><div class="field"><label>排序</label><input v-model.number="form.sort_no" type="number"></div><div class="field"><label>状态</label><FilterSelect v-model="form.status" :options="[{value:'active',label:'启用'},{value:'disabled',label:'停用'}]"/></div><div class="field full"><label>说明</label><input v-model="form.description"></div></div><h3>模板权限（数据权限）</h3><div class="table-wrap" style="max-height:46vh;overflow:auto"><table><thead><tr><th style="width:130px">功能模块</th><th>权限名称</th><th style="width:60px">类型</th><th>说明</th><th style="width:52px">允许</th></tr></thead><tbody><tr v-for="item in modules" :key="item.code"><td>{{item.module}}</td><td>{{item.name}}</td><td>{{kindText[item.kind]||item.kind}}</td><td class="text-muted">{{item.description}}</td><td><input v-model="selectedPermissions[item.code]" type="checkbox"></td></tr></tbody></table></div><template #footer><button class="button secondary" @click="closeModal">取消</button><button class="button" :disabled="saving" @click="current?saveTemplate():createTemplate()">{{current?'保存模板及权限':'创建模板'}}</button></template></ModalDialog></div></template>
